# All rights reserved. Unauthorized copying, distribution, or modification of this script is prohibited.

$ErrorActionPreference = "Stop"

# ============================================================
# CONFIG
# ============================================================

$MainDir            = "C:\Windows\System32\Acceleron"
$BaseDir            = Join-Path $MainDir "Updater"
$CertDir            = Join-Path $MainDir "Certificate"

$UpdaterPath        = Join-Path $BaseDir "Updater.exe"
$CertPath           = Join-Path $CertDir "AcceleronCertificate.cer"
$LogFile            = Join-Path $BaseDir "Updater.log"
$PolicyConfigPath   = Join-Path $BaseDir "Policies.json"

$UpdaterTaskName    = "Acceleron Updater"
$UpdatertempXml     = "$env:TEMP\Updater.xml"

$PinnedThumbprint   = "C9C559D901C9B31C90AF64D0D20A091013A3D4C3"

$IsSystem           = ([Security.Principal.WindowsIdentity]::GetCurrent().IsSystem)
$IsAdmin            = ([Security.Principal.WindowsPrincipal] `
                      [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

# ============================================================
# ENSURE BASE DIRECTORY
# ============================================================

# Create base directory if not exists
if (-not (Test-Path $BaseDir)) {
    New-Item -Path $BaseDir -ItemType Directory -Force | Out-Null
}

# Create certificate directory if not exists
if (-not (Test-Path $CertDir)) {
    New-Item -Path $CertDir -ItemType Directory -Force | Out-Null
}

if (-not (Test-Path $LogFile)) {
    New-Item -Path $LogFile -ItemType File | Out-Null
}

# ============================================================
# CLEAN OLD TASKS (SAFE)
# ============================================================


# Stop and temporarily disable the updater task so it cannot respawn Updater.exe
try {
    $existingTask = Get-ScheduledTask -TaskName $UpdaterTaskName -ErrorAction SilentlyContinue
    if ($existingTask) {
        Stop-ScheduledTask -TaskName $UpdaterTaskName -ErrorAction SilentlyContinue
        Disable-ScheduledTask -TaskName $UpdaterTaskName -ErrorAction SilentlyContinue | Out-Null
        Start-Sleep -Seconds 2
    }
} catch {
    # Write-Warning "Unable to stop/disable scheduled task '$UpdaterTaskName': $($_.Exception.Message)"
}

# Stop only Updater.exe instances whose executable path exactly matches the installed target.
# Repeat until the process exits; task is disabled to prevent automatic respawn during replacement.
$ProcessWaitSeconds = 30
$ProcessDeadline = (Get-Date).AddSeconds($ProcessWaitSeconds)

do {
    $AllUpdaterProcesses = @(Get-CimInstance Win32_Process -Filter "Name='Updater.exe'" -ErrorAction SilentlyContinue)
    $MatchingUpdaterProcesses = @($AllUpdaterProcesses | Where-Object {
        $_.ExecutablePath -and
        [string]::Equals($_.ExecutablePath, $UpdaterPath, [StringComparison]::OrdinalIgnoreCase)
    })

    if ($MatchingUpdaterProcesses.Count -eq 0) {
        break
    }

    foreach ($UpdaterProc in $MatchingUpdaterProcesses) {
        try {
            Stop-Process -Id ([int]$UpdaterProc.ProcessId) -Force -ErrorAction Stop
        } catch {
            # Write-Warning "Could not terminate Updater.exe PID $($UpdaterProc.ProcessId): $($_.Exception.Message)"
        }
    }

    Start-Sleep -Milliseconds 750
} while ((Get-Date) -lt $ProcessDeadline)

# Final verification: do not replace the EXE if a matching process remains.
$RemainingUpdaterProcesses = @(Get-CimInstance Win32_Process -Filter "Name='Updater.exe'" -ErrorAction SilentlyContinue |
    Where-Object {
        $_.ExecutablePath -and
        [string]::Equals($_.ExecutablePath, $UpdaterPath, [StringComparison]::OrdinalIgnoreCase)
    })

if ($RemainingUpdaterProcesses.Count -gt 0) {
    $ProcessDetails = ($RemainingUpdaterProcesses | ForEach-Object {
        "PID=$($_.ProcessId); ExecutablePath=$($_.ExecutablePath); CommandLine=$($_.CommandLine)"
    }) -join [Environment]::NewLine

    throw "Updater.exe is still running after $ProcessWaitSeconds seconds. Replacement aborted.`n$ProcessDetails"
}

if (Test-Path $PolicyConfigPath) {
    Remove-Item $PolicyConfigPath -Force -ErrorAction SilentlyContinue | Out-Null
}

# ============================================================
# UPDATER DIRECTORY POLICY CONFIGURATION (POWERSHELL-OWNED)
# ============================================================
# Policies.json is stored beside Updater.exe in the Updater directory.
# PowerShell creates the initial configuration only when missing. Updater.exe CLI
# supports list/add/update/remove for future policy changes. Binary updates preserve this file.
if (-not (Test-Path $PolicyConfigPath)) {
        $PolicyConfig = [ordered]@{
            Policies = @(
                [ordered]@{
                    Name = "Wallpaper"
                    Message = "Applying Wallpaper Policy"
                    Url = "https://github.com/bprasad884uu/Gainwell/raw/refs/heads/main/Wallpaper/WallpaperPolicy.ps1"
                    RepoPath = "Wallpaper/WallpaperPolicy.ps1"
                    StateFile = "WallpaperPolicy.sha"
                    Files = @(
                        "C:\Windows\System32\Acceleron\Wallpaper\WallpaperPolicy.exe",
                        "C:\Windows\System32\Acceleron\Wallpaper\WallpaperUpdate.exe",
                        "C:\Windows\Web\Wallpaper\Windows\Wallpaper.jpg"
                    )
                    Tasks = @("Wallpaper Policy", "Wallpaper Update Schedule")
                    Services = @()
                },
                [ordered]@{
                    Name = "Screensaver"
                    Message = "Applying Screensaver Policy"
                    Url = "https://github.com/bprasad884uu/Gainwell/raw/refs/heads/main/Screensaver/Screensaver-Policy.ps1"
                    RepoPath = "Screensaver/Screensaver-Policy.ps1"
                    StateFile = "ScreensaverPolicy.sha"
                    Files = @(
                        "C:\Windows\System32\Acceleron\Screensaver\CorpSaver.scr",
                        "C:\Windows\Web\Screensaver\*-*.jpg"
                    )
                    Tasks = @()
                    Services = @()
                },
                [ordered]@{
                    Name = "Winget"
                    Message = "Applying Winget Policy"
                    Url = "https://github.com/bprasad884uu/Gainwell/raw/refs/heads/main/Winget_Upgrade.ps1"
                    RepoPath = "Winget_Upgrade.ps1"
                    StateFile = "WingetUpgrade.sha"
                    Files = @("C:\Windows\System32\Acceleron\Winget\winget.exe")
                    Tasks = @("Winget Upgrade Policy")
                    Services = @()
                },
                [ordered]@{
                    Name = "ExcelPatchGuard"
                    Message = "Applying Excel Policy"
                    Url = "https://github.com/bprasad884uu/Gainwell/raw/refs/heads/main/Excel/Stop-Excel-Patch.ps1"
                    RepoPath = "Excel/Stop-Excel-Patch.ps1"
                    StateFile = "StopExcelPatch.sha"
                    Files = @("C:\Windows\System32\Acceleron\ExcelPatchGuard\ExcelPatchGuard.exe")
                    Tasks = @()
                    Services = @("ExcelPatchGuard")
                },
                [ordered]@{
                    Name = "AppLocker"
                    Message = "Applying App Locker Policy"
                    Url = "https://github.com/bprasad884uu/Gainwell/raw/refs/heads/main/App-Block/AppLocker.ps1"
                    RepoPath = "App-Block/AppLocker.ps1"
                    StateFile = "AppLockerPolicy.sha"
                    Files = @(
                        "C:\Windows\System32\Acceleron\Applocker\AppLocker.exe",
                        "C:\Windows\System32\Acceleron\Applocker\runtimesvc.exe"
                    )
                    Tasks = @("App Locker - Interactive User")
                    Services = @()
                }
            )
        }
        $PolicyJson = ConvertTo-Json -InputObject $PolicyConfig -Depth 10
        # ConvertTo-Json emits readable multi-line JSON (one property per line).
        [System.IO.File]::WriteAllText($PolicyConfigPath, $PolicyJson, ([System.Text.UTF8Encoding]::new($false)))
        Write-Output "Created initial policy configuration.
}

# ============================================================
# EMBEDDED BINARIES (BASE64)
# ============================================================

$CertBase64 = @'

'@

$UpdaterBase64 = @'

'@

# ============================================================
# DECODE EXEs
# ============================================================

$UpdaterExeBytes = [Convert]::FromBase64String($UpdaterBase64)

# ============================================================
# WRITE + TRUST CERTIFICATE (SYSTEM ONLY)
# ============================================================

if ($IsSystem -or $IsAdmin) {

    if (-not (Test-Path $CertPath)) {
        [IO.File]::WriteAllBytes(
            $CertPath,
            [Convert]::FromBase64String($CertBase64)
        )
    }

    foreach ($store in @(
        "Root",
        "TrustedPublisher"
    )) {
        if (-not (certutil -store $store | Select-String $PinnedThumbprint)) {
            & certutil.exe -addstore $store $CertPath | Out-Null
        }
    }
}

# ============================================================
# WRITE UPDATER EXE
# ============================================================

[IO.File]::WriteAllBytes(
    $UpdaterPath,
    $UpdaterExeBytes
)

$Sig = Get-AuthenticodeSignature -FilePath $UpdaterPath

if (
    -not $Sig.SignerCertificate -or
    $Sig.SignerCertificate.Thumbprint -ne $PinnedThumbprint -or
    $Sig.Status -in @(
        'HashMismatch',
        'NotSigned',
        'UnknownError'
    )
) {
    throw "Updater.exe signature validation failed. Status: $($Sig.Status)"
}

# ------------------------------------------------------------
# SCHEDULED TASK: APP LOCKER (INTERACTIVE USER)
# ------------------------------------------------------------

# Generate correct timestamp
$startTime = (Get-Date).AddMinutes(1).ToString("yyyy-MM-ddTHH:mm:ss")

# ---------------- CLEAN OLD TASK ----------------

Unregister-ScheduledTask -TaskName $UpdaterTaskName -Confirm:$false -ErrorAction SilentlyContinue

# ---------------- CREATE UPDATER XML ----------------

$UpdaterXml = @"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.4" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo>
    <Author>Acceleron</Author>
    <URI>\$UpdaterTaskName</URI>
  </RegistrationInfo>
  <Triggers>
    <LogonTrigger>
      <Enabled>true</Enabled>
    </LogonTrigger>
    <TimeTrigger>
      <StartBoundary>$startTime</StartBoundary>
      <Enabled>true</Enabled>
    </TimeTrigger>
  </Triggers>
  <Principals>
    <Principal id="Author">
      <GroupId>S-1-5-18</GroupId>
      <RunLevel>HighestAvailable</RunLevel>
    </Principal>
  </Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>true</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
    <IdleSettings>
      <StopOnIdleEnd>true</StopOnIdleEnd>
      <RestartOnIdle>false</RestartOnIdle>
    </IdleSettings>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled>
    <Hidden>false</Hidden>
    <RunOnlyIfIdle>false</RunOnlyIfIdle>
    <WakeToRun>false</WakeToRun>
    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>
    <Priority>7</Priority>
  </Settings>
  <Actions Context="Author">
    <Exec>
      <Command>$UpdaterPath</Command>
    </Exec>
  </Actions>
</Task>
"@

# ---------------- SAVE XML ----------------

$UpdaterXml | Out-File -FilePath $UpdatertempXml -Encoding Unicode

# ---------------- REGISTER TASK ----------------

$null = Register-ScheduledTask -TaskName $UpdaterTaskName -Xml (Get-Content $UpdatertempXml | Out-String) -Force

# ------------------------------------------------------------
# Cleanup
# ------------------------------------------------------------

Remove-Item $UpdatertempXml -Force -ErrorAction SilentlyContinue

# Trigger immediately after registration. The task only runs if an interactive
# user token is available; it cannot fall back to SYSTEM.
try {
    Start-ScheduledTask -TaskName $UpdaterTaskName -ErrorAction Stop
    Start-Sleep -Seconds 3
} catch {
    # Write-Warning "Task is registered but could not start now. It will run at the next interactive logon. $($_.Exception.Message)"
}

# ------------------------------------------------------------
# Final output only
# ------------------------------------------------------------

# Clear applied Certificate
Remove-Item $CertDir -Recurse -Force -ErrorAction SilentlyContinue

Write-Host "Updater started."